int f(int[] array) {
  if (array == null || array.length == 0) {
    return 0;
  }
  int x = array[0];
  int y = 0;
  for (int i = 1; i < array.length; i++) {
    if (array[i] < x) {
      x = array[i];
      y = i;
    }
  }
  return y;
}

